/**
 * Pure game/room logic for the D&D turn tracker.
 *
 * This file runs both in Node.js (server mode) and in the browser (when a
 * tablet/phone hosts the room itself), so it has no dependencies.
 *
 * Rooms are plain JSON objects so they can be persisted as-is.
 * Every mutating function takes the requesting client's secret `clientId`
 * and throws a GameError when the request is invalid or not allowed.
 *
 * Identity model:
 *  - `clientId` is a secret random id generated by each browser and kept in
 *    localStorage. It is NEVER sent to other clients.
 *  - each member also gets a public `id` that is safe to share.
 *  - enemies have no owner: whoever is currently the DM controls them.
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.DndRooms = factory();
})(typeof self !== 'undefined' ? self : this, function () {
'use strict';

function randomBytes(n) {
  const out = new Uint8Array(n);
  const c = typeof globalThis !== 'undefined' && globalThis.crypto && globalThis.crypto.getRandomValues
    ? globalThis.crypto
    : require('crypto').webcrypto;
  c.getRandomValues(out);
  return out;
}

const CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no 0/O, 1/I
const CODE_LENGTH = 5;

const LIMITS = {
  name: 40,
  cls: 40,
  statKey: 24,
  statValue: 60,
  stats: 12,
  combatants: 150,
  enemyBatch: 20,
  log: 60,
  members: 30,
};

const TYPES = ['pc', 'companion', 'enemy'];

class GameError extends Error {}

function randomId(bytes = 9) {
  return Array.from(randomBytes(bytes), (b) => b.toString(16).padStart(2, '0')).join('');
}

function randomCode(length = CODE_LENGTH) {
  let out = '';
  const bytes = randomBytes(length);
  for (let i = 0; i < length; i++) out += CODE_ALPHABET[bytes[i] % CODE_ALPHABET.length];
  return out;
}

function normalizeCode(code) {
  return String(code ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 12);
}

/* ------------------------------------------------------------------ */
/* Input sanitizing                                                    */
/* ------------------------------------------------------------------ */

function str(value, max) {
  return String(value ?? '')
    .replace(/[\u0000-\u001f\u007f]/g, ' ')
    .trim()
    .slice(0, max);
}

function int(value, min, max, fallback) {
  const n = Number.parseInt(value, 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

function initiativeValue(value, fallback = 0) {
  const n = Number.parseFloat(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.round(Math.min(99, Math.max(-20, n)) * 100) / 100;
}

function cleanStats(stats) {
  if (!Array.isArray(stats)) return [];
  const out = [];
  for (const s of stats) {
    if (!s || typeof s !== 'object') continue;
    const key = str(s.key, LIMITS.statKey);
    const value = str(s.value, LIMITS.statValue);
    if (!key && !value) continue;
    out.push({ key: key || 'Stat', value });
    if (out.length >= LIMITS.stats) break;
  }
  return out;
}

function cleanName(name) {
  const n = str(name, 30);
  if (!n) throw new GameError('Please enter your name.');
  return n;
}

/* ------------------------------------------------------------------ */
/* Room lifecycle                                                      */
/* ------------------------------------------------------------------ */

/**
 * Create a room. The creator is the DM, unless `opts.screen` is set: then the
 * creating device is a shared "table screen" (it hosts and shows the fight
 * but cannot act), and the DM joins from their own phone with the DM key.
 */
function createRoom(existingCodes, clientId, playerName, opts = {}) {
  if (!clientId) throw new GameError('Missing client id.');
  const name = cleanName(playerName);
  let code;
  do code = randomCode(); while (existingCodes.has(code));

  const now = Date.now();
  const room = {
    code,
    createdAt: now,
    updatedAt: now,
    dmKey: randomCode(6),
    members: {},
    combatants: [],
    nextOrder: 1,
    combat: { active: false, round: 0, turnId: null, cursor: null, seq: 0 },
    settings: { revealEnemies: false },
    log: [],
  };
  if (opts.screen) {
    room.members[clientId] = { id: randomId(), name, role: 'screen', joinedAt: now };
    addLog(room, `${name} (table screen) created the room. The DM joins with the DM key.`);
  } else {
    room.members[clientId] = { id: randomId(), name, role: 'dm', joinedAt: now };
    addLog(room, `${name} created the room and is the Dungeon Master.`);
  }
  return room;
}

/**
 * Join (or re-join) a room. A known clientId keeps its role.
 * Passing the room's DM key makes the caller the DM (the previous DM
 * becomes a regular player).
 */
function joinRoom(room, clientId, playerName, dmKey) {
  if (!clientId) throw new GameError('Missing client id.');
  const name = cleanName(playerName);
  let member = room.members[clientId];
  const wantsDm = dmKey != null && String(dmKey).trim() !== '';

  if (wantsDm && String(dmKey).trim().toUpperCase() !== room.dmKey) {
    throw new GameError('Wrong DM key.');
  }

  if (!member) {
    if (Object.keys(room.members).length >= LIMITS.members) throw new GameError('This room is full.');
    member = { id: randomId(), name, role: 'player', joinedAt: Date.now() };
    room.members[clientId] = member;
    addLog(room, `${name} joined the room.`);
  } else if (member.name !== name) {
    addLog(room, `${member.name} is now called ${name}.`);
    member.name = name;
  }

  if (wantsDm && member.role === 'screen') throw new GameError('The table screen cannot become the DM.');
  if (wantsDm && member.role !== 'dm') {
    for (const m of Object.values(room.members)) if (m.role === 'dm') m.role = 'player';
    member.role = 'dm';
    addLog(room, `${name} is now the Dungeon Master.`);
  }
  touch(room);
  return member;
}

function getMember(room, clientId) {
  const m = room.members[clientId];
  if (!m) throw new GameError('You are not part of this room. Please re-join.');
  return m;
}

function memberById(room, publicId) {
  return Object.values(room.members).find((m) => m.id === publicId) || null;
}

function dmMember(room) {
  return Object.values(room.members).find((m) => m.role === 'dm') || null;
}

function touch(room) {
  room.updatedAt = Date.now();
}

function addLog(room, publicText, dmText) {
  room.log.push({ t: Date.now(), text: publicText, dm: dmText && dmText !== publicText ? dmText : undefined });
  if (room.log.length > LIMITS.log) room.log.splice(0, room.log.length - LIMITS.log);
}

/* ------------------------------------------------------------------ */
/* Combatants                                                          */
/* ------------------------------------------------------------------ */

function findCombatant(room, id) {
  const c = room.combatants.find((x) => x.id === id);
  if (!c) throw new GameError('That creature no longer exists.');
  return c;
}

function canControl(room, member, c) {
  if (member.role === 'dm') return true;
  return c.type !== 'enemy' && c.owner === member.id;
}

function buildFields(input, existing) {
  const hpMax = int(input.hpMax, 1, 9999, existing ? existing.hpMax : 10);
  let hp = int(input.hp, 0, 9999, existing ? existing.hp : hpMax);
  // keep current HP sensible when only max HP changes
  if (input.hp === undefined || input.hp === null || input.hp === '') hp = existing ? Math.min(existing.hp, hpMax) : hpMax;
  hp = Math.min(hp, hpMax);
  return {
    name: str(input.name, LIMITS.name),
    cls: str(input.cls, LIMITS.cls),
    level: int(input.level, 0, 30, existing ? existing.level : 1),
    hpMax,
    hp,
    ac: int(input.ac, 0, 50, existing ? existing.ac : 10),
    initiative: initiativeValue(input.initiative, existing ? existing.initiative : 0),
    initBonus: int(input.initBonus, -10, 20, existing ? existing.initBonus || 0 : 0),
    stats: cleanStats(input.stats),
  };
}

/**
 * Create or update a combatant. Returns the list of created/updated combatants.
 */
function saveCombatant(room, clientId, input) {
  const member = getMember(room, clientId);
  if (!input || typeof input !== 'object') throw new GameError('Invalid data.');

  // ---- update ----
  if (input.id) {
    const c = findCombatant(room, input.id);
    if (!canControl(room, member, c)) throw new GameError('You cannot edit this creature.');
    const f = buildFields(input, c);
    if (!f.name) throw new GameError('Name is required.');
    const before = c.hp;
    Object.assign(c, f);
    if (c.type === 'enemy' && input.hidden !== undefined) {
      const wasHidden = c.hidden;
      c.hidden = Boolean(input.hidden);
      if (wasHidden && !c.hidden) addLog(room, `${c.name} joined the fight!`);
    }
    if (before > 0 && c.hp === 0 && c.type === 'enemy') addLog(room, `${c.name} is defeated!`);
    touch(room);
    return [c];
  }

  // ---- create ----
  const type = TYPES.includes(input.type) ? input.type : null;
  if (!type) throw new GameError('Unknown creature type.');
  const f = buildFields(input, null);
  if (!f.name) throw new GameError('Name is required.');

  if (type === 'enemy') {
    if (member.role !== 'dm') throw new GameError('Only the Dungeon Master can add enemies.');
    const count = int(input.count, 1, LIMITS.enemyBatch, 1);
    if (room.combatants.length + count > LIMITS.combatants) throw new GameError('Too many creatures in this room.');
    const created = [];
    for (let i = 0; i < count; i++) {
      const c = {
        id: randomId(),
        type,
        owner: null,
        order: room.nextOrder++,
        hidden: Boolean(input.hidden),
        ...f,
        stats: f.stats.map((s) => ({ ...s })),
        name: count > 1 ? `${f.name} ${i + 1}`.slice(0, LIMITS.name + 3) : f.name,
      };
      room.combatants.push(c);
      created.push(c);
    }
    const label = count > 1 ? `${count}× ${f.name}` : f.name;
    // hidden creatures are only announced to the DM
    if (input.hidden) addLog(room, '', `The DM prepared ${label} (hidden).`);
    else addLog(room, `${label} joined the fight!`);
    touch(room);
    return created;
  }

  // pc / companion: one of each per player
  if (member.role === 'screen') throw new GameError('The table screen only displays the fight.');
  if (member.role === 'dm') throw new GameError('The Dungeon Master controls enemies; players add their own characters.');
  const already = room.combatants.find((c) => c.owner === member.id && c.type === type);
  if (already) {
    throw new GameError(type === 'pc' ? 'You already have a character. Edit it instead.' : 'Each player can only have one friendly NPC.');
  }
  if (room.combatants.length >= LIMITS.combatants) throw new GameError('Too many creatures in this room.');
  const c = { id: randomId(), type, owner: member.id, order: room.nextOrder++, hidden: false, ...f };
  room.combatants.push(c);
  addLog(room, type === 'pc' ? `${member.name} added the character ${c.name}.` : `${member.name} brought along ${c.name} (friendly NPC).`);
  touch(room);
  return [c];
}

function removeCombatant(room, clientId, id) {
  const member = getMember(room, clientId);
  const c = findCombatant(room, id);
  if (!canControl(room, member, c)) throw new GameError('You cannot remove this creature.');
  const wasCurrent = room.combat.active && room.combat.turnId === c.id;
  room.combatants = room.combatants.filter((x) => x.id !== id);
  if (!c.hidden) addLog(room, `${c.name} left the fight.`);
  if (wasCurrent) {
    room.combat.turnId = null;
    advance(room, +1);
  }
  touch(room);
}

/**
 * Apply damage or healing.
 *  - DM: anything.
 *  - Player: damage enemies or their own creatures; heal any PC / friendly NPC.
 */
function changeHp(room, clientId, { targetId, amount, mode, attackerId } = {}) {
  const member = getMember(room, clientId);
  const target = findCombatant(room, targetId);
  const value = int(amount, 0, 9999, 0);
  if (value <= 0) throw new GameError('Enter an amount greater than 0.');
  if (mode !== 'damage' && mode !== 'heal') throw new GameError('Invalid action.');
  if (member.role === 'screen') throw new GameError('The table screen only displays the fight.');

  const isDm = member.role === 'dm';
  if (!isDm) {
    if (target.hidden) throw new GameError('That creature no longer exists.');
    if (mode === 'damage' && target.type !== 'enemy' && target.owner !== member.id) {
      throw new GameError('You can only damage enemies or your own creatures.');
    }
    if (mode === 'heal' && target.type === 'enemy') throw new GameError('You cannot heal enemies.');
  }

  let attacker = null;
  if (attackerId) {
    attacker = room.combatants.find((x) => x.id === attackerId) || null;
    if (attacker && !canControl(room, member, attacker)) attacker = null;
  }
  const who = attacker ? attacker.name : member.name;

  const before = target.hp;
  if (mode === 'damage') target.hp = Math.max(0, target.hp - value);
  else target.hp = Math.min(target.hpMax, target.hp + value);
  const after = target.hp;

  const secret = target.type === 'enemy' && !room.settings.revealEnemies;
  const nums = ` (${before} → ${after} HP)`;
  if (mode === 'damage') {
    const base = `${who} dealt ${value} damage to ${target.name}`;
    addLog(room, secret ? `${base}.` : `${base}${nums}.`, `${base}${nums}.`);
    if (before > 0 && after === 0) {
      addLog(room, target.type === 'enemy' ? `💀 ${target.name} is defeated!` : `⚠️ ${target.name} drops to 0 HP!`);
    }
  } else {
    const base = `${who} healed ${target.name} for ${value}`;
    addLog(room, secret ? `${base}.` : `${base}${nums}.`, `${base}${nums}.`);
  }
  touch(room);
  return target;
}

/* ------------------------------------------------------------------ */
/* Turn order                                                          */
/* ------------------------------------------------------------------ */

function sortKey(c) {
  return [c.initiative, c.order];
}

/** negative if a acts before b */
function compareKeys(a, b) {
  if (a[0] !== b[0]) return b[0] - a[0]; // higher initiative first
  return a[1] - b[1]; // then whoever was added first
}

function sortedCombatants(room) {
  return [...room.combatants].sort((a, b) => compareKeys(sortKey(a), sortKey(b)));
}

/** Creatures that actually get a turn: visible, and enemies must be alive. */
function eligible(room) {
  return sortedCombatants(room).filter((c) => !c.hidden && !(c.type === 'enemy' && c.hp <= 0));
}

function setCurrent(room, c) {
  room.combat.turnId = c.id;
  room.combat.cursor = sortKey(c);
  room.combat.seq += 1;
}

/**
 * Move the turn pointer forward (+1) or back (-1). Works off a "cursor"
 * (initiative + insertion order of the last current creature), so it keeps
 * working even if the current creature was removed or edited.
 */
function advance(room, dir) {
  const list = eligible(room);
  if (list.length === 0) {
    room.combat.turnId = null;
    room.combat.seq += 1;
    return null;
  }
  const cursor = room.combat.cursor;
  let next = null;
  if (!cursor) {
    next = list[0];
  } else if (dir > 0) {
    next = list.find((c) => compareKeys(sortKey(c), cursor) > 0) || null;
    if (!next) {
      next = list[0];
      room.combat.round += 1;
      addLog(room, `— Round ${room.combat.round} —`);
    }
  } else {
    const before = list.filter((c) => compareKeys(sortKey(c), cursor) < 0);
    next = before[before.length - 1] || null;
    if (!next) {
      next = list[list.length - 1];
      room.combat.round = Math.max(1, room.combat.round - 1);
    }
  }
  setCurrent(room, next);
  return next;
}

function requireDm(member) {
  if (member.role !== 'dm') throw new GameError('Only the Dungeon Master can do that.');
}

function startCombat(room, clientId) {
  const member = getMember(room, clientId);
  requireDm(member);
  const list = eligible(room);
  if (list.length === 0) throw new GameError('Add some creatures first.');
  room.combat.active = true;
  room.combat.round = 1;
  room.combat.cursor = null;
  addLog(room, '⚔️ Combat started! — Round 1 —');
  advance(room, +1);
  touch(room);
}

function endCombat(room, clientId) {
  const member = getMember(room, clientId);
  requireDm(member);
  room.combat.active = false;
  room.combat.turnId = null;
  room.combat.cursor = null;
  room.combat.round = 0;
  room.combat.seq += 1;
  addLog(room, '🏳️ Combat ended.');
  touch(room);
}

/** DM, or the player whose creature is acting, can end the turn. */
function nextTurn(room, clientId) {
  const member = getMember(room, clientId);
  if (!room.combat.active) throw new GameError('Combat has not started.');
  const current = room.combatants.find((c) => c.id === room.combat.turnId);
  if (member.role !== 'dm' && !(current && canControl(room, member, current))) {
    throw new GameError("It's not your turn.");
  }
  advance(room, +1);
  touch(room);
}

function prevTurn(room, clientId) {
  const member = getMember(room, clientId);
  requireDm(member);
  if (!room.combat.active) throw new GameError('Combat has not started.');
  advance(room, -1);
  touch(room);
}

function setTurn(room, clientId, id) {
  const member = getMember(room, clientId);
  requireDm(member);
  if (!room.combat.active) throw new GameError('Combat has not started.');
  const c = findCombatant(room, id);
  if (c.hidden) throw new GameError('Reveal this creature first.');
  setCurrent(room, c);
  touch(room);
}

function updateSettings(room, clientId, settings = {}) {
  const member = getMember(room, clientId);
  requireDm(member);
  if (settings.revealEnemies !== undefined) room.settings.revealEnemies = Boolean(settings.revealEnemies);
  touch(room);
}

/* ------------------------------------------------------------------ */
/* Per-client view                                                     */
/* ------------------------------------------------------------------ */

function hpStatus(c) {
  if (c.hp <= 0) return 'Defeated';
  const pct = c.hp / c.hpMax;
  if (pct >= 1) return 'Unharmed';
  if (pct > 0.5) return 'Injured';
  if (pct > 0.25) return 'Bloodied';
  return 'Near death';
}

/**
 * Build the state a given client is allowed to see. Secret client ids and
 * the DM key never leave the server except the DM key for the DM.
 */
const ROLE_ORDER = { dm: 0, screen: 1, player: 2 };

function viewFor(room, clientId, isOnline = () => false) {
  const me = room.members[clientId];
  if (!me) return null;
  const isDm = me.role === 'dm';
  const reveal = isDm || room.settings.revealEnemies;
  const ownerName = new Map(Object.values(room.members).map((m) => [m.id, m.name]));

  const current = room.combat.active ? room.combatants.find((c) => c.id === room.combat.turnId) : null;

  const combatants = sortedCombatants(room)
    .filter((c) => isDm || !c.hidden)
    .map((c) => {
      const secret = c.type === 'enemy' && !reveal;
      return {
        id: c.id,
        type: c.type,
        owner: c.owner,
        ownerName: c.owner ? ownerName.get(c.owner) || '?' : 'DM',
        name: c.name,
        cls: c.cls,
        level: c.level,
        initiative: c.initiative,
        initBonus: secret ? null : c.initBonus || 0,
        hidden: Boolean(c.hidden),
        hp: secret ? null : c.hp,
        hpMax: secret ? null : c.hpMax,
        hpPct: Math.round((c.hp / c.hpMax) * 100),
        status: hpStatus(c),
        ac: secret ? null : c.ac,
        stats: secret ? [] : c.stats,
        mine: canControl(room, me, c) && (c.type !== 'enemy' || isDm),
        defeated: c.hp <= 0,
      };
    });

  const yourTurn = Boolean(current && (current.type === 'enemy' ? isDm : current.owner === me.id));

  return {
    code: room.code,
    you: { id: me.id, name: me.name, role: me.role },
    dmKey: isDm || me.role === 'screen' ? room.dmKey : undefined,
    members: Object.entries(room.members)
      .map(([cid, m]) => ({ id: m.id, name: m.name, role: m.role, online: isOnline(cid) }))
      .sort((a, b) => ROLE_ORDER[a.role] - ROLE_ORDER[b.role] || a.name.localeCompare(b.name)),
    combatants,
    combat: {
      active: room.combat.active,
      round: room.combat.round,
      turnId: current && (isDm || !current.hidden) ? current.id : null,
      seq: room.combat.seq,
    },
    yourTurn,
    settings: { ...room.settings },
    log: room.log
      .map((l) => ({ t: l.t, text: isDm && l.dm ? l.dm : l.text }))
      .filter((l) => l.text)
      .slice(-40),
  };
}

return {
  GameError,
  LIMITS,
  normalizeCode,
  createRoom,
  joinRoom,
  getMember,
  memberById,
  dmMember,
  saveCombatant,
  removeCombatant,
  changeHp,
  startCombat,
  endCombat,
  nextTurn,
  prevTurn,
  setTurn,
  updateSettings,
  sortedCombatants,
  eligible,
  viewFor,
  hpStatus,
};
});
